const Cart=function(){function storageKey(storeSlug){return"skiri_cart_"+storeSlug}function getCart(storeSlug){try{return JSON.parse(localStorage.getItem(storageKey(storeSlug)))||[]}catch(err){return[]}}function saveCart(storeSlug,cart){localStorage.setItem(storageKey(storeSlug),JSON.stringify(cart))}function minQtyOf(line){const n=Number(line&&line.minQty);return n>1&&Math.floor(n)===n?n:1}function unitPriceOf(line){const base=Math.round(Number(line.unitPrice)*100)/100;let price=base;(Array.isArray(line.tiers)?line.tiers:[]).forEach(t=>{if(t&&Number(line.qty)>=Number(t.minQty)&&Number(t.price)>0)price=Math.round(Number(t.price)*100)/100});return Math.min(price,base)}function lineTotal(line){return Math.round(unitPriceOf(line)*line.qty*100)/100}function nextTierOf(line){const tiers=Array.isArray(line.tiers)?line.tiers:[];return tiers.find(t=>t&&Number(t.minQty)>Number(line.qty)&&Number(t.price)<unitPriceOf(line))||null}function addItem(storeSlug,item){const cart=getCart(storeSlug);const existing=cart.find(line=>line.variantId===item.variantId);if(existing){existing.qty+=item.qty;if(item.tiers!==undefined||item.minQty!==undefined){existing.tiers=item.tiers;existing.minQty=item.minQty;existing.unitPrice=item.unitPrice}existing.qty=Math.max(existing.qty,minQtyOf(existing))}else{cart.push(Object.assign({},item,{qty:Math.max(item.qty,minQtyOf(item))}))}saveCart(storeSlug,cart);return cart}function updateQty(storeSlug,variantId,qty){let cart=getCart(storeSlug);if(qty<=0){cart=cart.filter(line=>line.variantId!==variantId)}else{cart.forEach(line=>{if(line.variantId===variantId)line.qty=Math.max(qty,minQtyOf(line))})}saveCart(storeSlug,cart);return cart}function removeItem(storeSlug,variantId){return updateQty(storeSlug,variantId,0)}function clearCart(storeSlug){saveCart(storeSlug,[])}function getTotal(storeSlug){return getCart(storeSlug).reduce((sum,line)=>sum+lineTotal(line),0)}function getItemCount(storeSlug){return getCart(storeSlug).reduce((sum,line)=>sum+line.qty,0)}function getDistinctProductCount(storeSlug){const ids={};getCart(storeSlug).forEach(line=>{ids[line.productId]=true});return Object.keys(ids).length}return{getCart:getCart,addItem:addItem,updateQty:updateQty,removeItem:removeItem,clearCart:clearCart,getTotal:getTotal,getItemCount:getItemCount,getDistinctProductCount:getDistinctProductCount,unitPriceOf:unitPriceOf,lineTotal:lineTotal,minQtyOf:minQtyOf,nextTierOf:nextTierOf}}();